using System.Security.Cryptography;
using System.Text;
using System.Text.Json;

namespace Karry.Spikes.SignatureInterop.Tests;

/// <summary>
/// WP-P0-11 interop: a signature produced by Chromium WebCrypto (ECDSA P-256, SHA-256,
/// IEEE P1363 r||s encoding) must verify with .NET, which will run the real server.
/// The fixture is regenerated by the PWA spike (UPDATE_SIGNATURE_VECTOR=1, TC-P0-KEY-003).
/// </summary>
public sealed class BrowserSignatureVerificationTests
{
    private static readonly Vector Fixture = Vector.Load();

    [Fact, Trait("TestCase", "TC-P0-SIG-001"), Trait("WorkPackage", "WP-P0-11")]
    public void Browser_signature_verifies_with_dotnet()
    {
        using var key = Fixture.PublicKey();
        var valid = key.VerifyData(Encoding.UTF8.GetBytes(Fixture.CanonicalPayload), Fixture.SignatureBytes(),
            HashAlgorithmName.SHA256, DSASignatureFormat.IeeeP1363FixedFieldConcatenation);
        Assert.True(valid);
    }

    [Fact, Trait("TestCase", "TC-P0-SIG-002"), Trait("WorkPackage", "WP-P0-11")]
    public void Payload_hash_computed_by_dotnet_matches_the_browser()
    {
        var hash = Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes(Fixture.CanonicalPayload)));
        Assert.Equal(Fixture.PayloadHash, hash);
    }

    [Fact, Trait("TestCase", "TC-P0-SIG-003"), Trait("WorkPackage", "WP-P0-11")]
    public void Modified_payload_is_rejected()
    {
        using var key = Fixture.PublicKey();
        var tampered = Fixture.CanonicalPayload.Replace("\"meterStart\":", "\"meterStart\":9", StringComparison.Ordinal);
        Assert.NotEqual(Fixture.CanonicalPayload, tampered);
        Assert.False(key.VerifyData(Encoding.UTF8.GetBytes(tampered), Fixture.SignatureBytes(),
            HashAlgorithmName.SHA256, DSASignatureFormat.IeeeP1363FixedFieldConcatenation));
    }

    [Fact, Trait("TestCase", "TC-P0-SIG-004"), Trait("WorkPackage", "WP-P0-11")]
    public void Der_format_assumption_would_reject_a_valid_browser_signature()
    {
        // Documents the classic interop trap: WebCrypto emits P1363 (64 bytes), not ASN.1 DER.
        using var key = Fixture.PublicKey();
        Assert.Equal(64, Fixture.SignatureBytes().Length);
        Assert.False(key.VerifyData(Encoding.UTF8.GetBytes(Fixture.CanonicalPayload), Fixture.SignatureBytes(),
            HashAlgorithmName.SHA256, DSASignatureFormat.Rfc3279DerSequence));
    }

    private sealed record Jwk(string Kty, string Crv, string X, string Y);

    private sealed record Vector(Jwk PublicKeyJwk, string CanonicalPayload, string PayloadHash, string Signature)
    {
        public static Vector Load()
        {
            var path = Path.Combine(AppContext.BaseDirectory, "fixtures", "browser-vector.json");
            return JsonSerializer.Deserialize<Vector>(File.ReadAllText(path), new JsonSerializerOptions(JsonSerializerDefaults.Web))
                ?? throw new InvalidOperationException("Empty signature fixture.");
        }

        public byte[] SignatureBytes() => Convert.FromBase64String(Signature);

        public ECDsa PublicKey()
        {
            Assert.Equal("EC", PublicKeyJwk.Kty);
            Assert.Equal("P-256", PublicKeyJwk.Crv);
            return ECDsa.Create(new ECParameters
            {
                Curve = ECCurve.NamedCurves.nistP256,
                Q = new ECPoint { X = Base64UrlDecode(PublicKeyJwk.X), Y = Base64UrlDecode(PublicKeyJwk.Y) },
            });
        }

        private static byte[] Base64UrlDecode(string value) => System.Buffers.Text.Base64Url.DecodeFromChars(value);
    }
}
